INSERT INTO `collections` (`id`, `slug`, `name`, `short_name`, `icon`, `icon_hover`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'point-source-speakers','Point source speakers','Point source','uploads/images/2026/10/collection-point-source-speakers-4b27cf.png','uploads/images/2026/10/collection-point-source-speakers-hover-3a437b.png',1,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(2,'slimline-array-speaker-systems','Slimline array speaker systems','Slimline array','uploads/images/2026/10/collection-slimline-array-speaker-systems-c775a5.png','uploads/images/2026/10/collection-slimline-array-speaker-systems-hover-762283.png',2,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(3,'high-performance-array-speaker-systems','High Performance array speaker systems','High performance array','uploads/images/2026/10/collection-high-performance-array-speaker-systems-751c5e.png','uploads/images/2026/10/collection-high-performance-array-speaker-systems-hover-e2940c.png',3,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(4,'ceiling-speakers','Ceiling speakers','Ceiling','uploads/images/2026/10/collection-ceiling-speakers-59072a.png','uploads/images/2026/10/collection-ceiling-speakers-hover-3a043b.png',4,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(5,'subwoofers','Subwoofers','Subwoofers','uploads/images/2026/10/collection-subwoofers-e07cc7.png','uploads/images/2026/10/collection-subwoofers-hover-b40c71.png',5,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(6,'amplifier-mixer','Amplifier & Mixer','Amplifier & Mixer','uploads/images/2026/10/collection-amplifier-mixer-d6091a.png','uploads/images/2026/10/collection-amplifier-mixer-hover-ca6c30.png',6,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(7,'microphones-headphones','Microphones and headphones','Microphones','uploads/images/2026/10/collection-microphones-headphones-2486b4.png','uploads/images/2026/10/collection-microphones-headphones-hover-c69601.png',7,1,'2026-10-11 22:05:00','2026-10-12 20:57:04'),(8,'accessories','Accessories and adaptors','Accessories','uploads/images/2026/10/collection-accessories-fc4a40.png','uploads/images/2026/10/collection-accessories-hover-227fc2.png',8,1,'2026-10-11 22:05:00','2026-10-12 20:57:04');
