INSERT INTO `posts` (`id`, `slug`, `title`, `excerpt`, `content`, `featured_image`, `is_published`, `published_at`, `author_id`, `created_at`, `updated_at`) VALUES (1,'frog-is-technology-provide-an-artistic-immersive-experience-in-immersion-shui-ting-men-drama-performance','Frog-is technology provides an artistic immersive experience in Immersion SHUI TING MEN Drama performance','The SHUI TING MEN Immersion drama performance provides an immersive artistic experience in which sound plays a key role and is successful from both a technical and aesthetic point of view. The entire audio team quickly…','<p>The SHUI TING MEN Immersion drama performance provides an immersive artistic experience in which sound plays a key role and is successful from both a technical and aesthetic point of view. The entire audio team quickly grew to create a multi-sensory performance by using Frog-is technology that enhanced the visual impact through equally engaging sound design, leaving an incredible impression on the audience.</p>\n<p>As visitors explore all the rooms with a range of exciting sights and sounds, we know they are getting an artistic immersive audio experience from Frog-is from start to finish.</p>\n<img alt=\"\" src=\"uploads/2023/12/STM.png\"/>','uploads/2023/12/STM-1.png',1,'2023-12-15 13:07:07',NULL,'2023-12-15 13:07:07','2026-09-29 10:55:40'),(2,'hk-island-school-has-adopted-frogis-brand-waterproof-speakers-and-audio-systems-for-high-quality-outdoor-sound-amplification','HK Island School has adopted Frogis brand waterproof speakers and audio systems for high-quality outdoor sound amplification.','We are excited to announce that Island School has adopted Frogis brand waterproof speakers and audio systems for high-quality outdoor sound amplification. These state-of-the-art audio devices deliver excellent sound…','<p>We are excited to announce that Island School has adopted Frogis brand waterproof speakers and audio systems for high-quality outdoor sound amplification. These state-of-the-art audio devices deliver excellent sound quality and volume while maintaining stability in various weather conditions. Whether it’s the school’s sports field, outdoor performance venues, or other event spaces, we can enjoy clear, dynamic music and voice amplification. With these innovative technologies, our school is able to provide students and teachers with richer and more engaging event experiences.</p>\n<img alt=\"\" src=\"uploads/2023/11/Island-School-.png\"/>','uploads/2023/11/Island-School-1.jpg',1,'2023-11-28 16:04:52',NULL,'2023-11-28 16:04:52','2025-04-09 12:03:45'),(3,'frog-is-has-been-awarded-for-audio-system-updated-for-hong-kong-dharma-drum-mountain-monastery','Frog-is has been awarded for audio system updated for Hong Kong Dharma Drum Mountain Monastery','Hong Kong Dharma Drum Mountain Monastery is a branch of Dharma Drum Mountain located in Lai Chi Kok, Hong Kong. The monastery serves as a religious, cultural, and educational center dedicated to promoting Buddhist…','<p>Hong Kong Dharma Drum Mountain Monastery is a branch of Dharma Drum Mountain located in Lai Chi Kok, Hong Kong. The monastery serves as a religious, cultural, and educational center dedicated to promoting Buddhist teachings, meditation, and humanistic values.</p>\n<p>Frog-is has been awarded for audio system updated at 1/F training rooms, and 2/F Main Hall.</p>\n<p>Today, Hong Kong Dharma Drum Mountain Monastery has become an important Buddhist center in Hong Kong, attracting many individuals to participate in its activities and bringing positive energy and w</p>\n<p>ell-being to society.</p>\n<img alt=\"\" src=\"uploads/2023/11/1.png\"/>','uploads/2023/11/01.jpg',1,'2023-11-16 13:58:51',NULL,'2023-11-16 13:58:51','2026-09-29 10:56:08'),(4,'frog-is-support-mas-ter-mic-concert-2023-produced-by-steven-ma','Frog-is supports “Ma’s Ter Mic Concert 2023” produced by Steven Ma','“Ma’s Ter Mic Concert 2023” produced by Steven Ma will begin with six performances at the Tung Wah Group of Hospitals Tung Pu Hu Lee Ming Ching Stadium. This performance is different from traditional concerts. Steven Ma…','<p>“Ma’s Ter Mic Concert 2023” produced by Steven Ma will begin with six performances at the Tung Wah Group of Hospitals Tung Pu Hu Lee Ming Ching Stadium.</p>\n<p>This performance is different from traditional concerts. Steven Ma staged an immersive art work, using Frogis speakers for sound effects, front fills and side stage main systems to lead the audience through the four seasons, giving every audience a sense of happiness to leave.</p>\n<img alt=\"\" src=\"uploads/2023/11/1-556fc4.jpg\"/>','uploads/2023/11/18b8b8b22ae1f12a49351f34f27d988.jpg',1,'2023-11-13 11:52:17',NULL,'2023-11-13 11:52:17','2026-09-29 10:56:28'),(5,'event-venue-keep-improving','Event venue, keep improving','Event venue, keep improving There are many reasons for running a venue, but we only think of this: We value the interaction between people. The world is changing today, and technology will advance tomorrow. We are…','<p><b>Event venue, keep improving</b></p>\n<p>There are many reasons for running a venue, but we only think of this: We value the interaction between people. The world is changing today, and technology will advance tomorrow. We are easily distracted by things, but when you think about it seriously, people are everything protagonist of things.</p>\n<p>Find the right place to shine</p>\n<p>SPARKMEN is dedicated to creating a place for people to communicate, so we provide a commercial event venue with professional equipment and reasonable prices. We seek to make every organizer and participant shine, and make everyone full of vitality and creativity.</p>\n<p>One of the selling points of the venue is the use of a full set of Frogis professional audio system, coupled with the sound insulation wall laid, output perfect sound, melodious music, making it easier to concentrate and drive the atmosphere of the event</p>\n<img alt=\"\" src=\"uploads/2023/08/HK-event-01-01.jpg\"/>','uploads/2023/08/HK-event-01-scaled.jpg',1,'2023-08-12 11:02:02',NULL,'2023-08-12 11:02:02','2025-04-09 12:04:42'),(6,'el-tiki-tapas-cocktail-bar-esotico','El Tiki Tapas Cocktail Bar Esotico','El Tiki Tapas Cocktail Bar Esotico El Tiki is a tapas and cocktail bar connecting Turin historic center to the lively, multi-ethnic neighborhood of San Salvario, heart of the city’s nightlife. The exotic interior…','<p><b>El Tiki Tapas Cocktail Bar Esotico</b></p>\n<p>El Tiki is a tapas and cocktail bar connecting Turin historic center to the lively, multi-ethnic neighborhood of San Salvario, heart of the city’s nightlife.</p>\n<p>The exotic interior concept by MTM Design takes you into a wild, colorful, urban jungle where you can let go and enjoy an amazing experience.</p>\n<p>The menu offers bright flavorful dishes of tapas to share and vibrant outlandish cocktails to sip at leisure.</p>\n<p>The staff is unobtrusively friendly and caring.</p>\n<p>This unique place is set up with a complete Frog-is sound system to match its adventurous spirit.</p>\n<p>Four discreet and elegant FS15-Array powered by two compact FS-Sub15 active Sub-Woofers provide all the punch needed in the main Lounge area, while two FI-SMS4B two-way speakers, one FI-Sub6P ultra-compact subwoofer, three FI-CS4W ceiling speakers, powered by two FI-Amp4D class D amplifiers provide quality sound in every corner of the bar. One FI-P4X8+ digital processor allows easy, intuitive configuration and control of the speakers.</p>\n<p>One FI-Mix8 compact analog 8 In x 2 Out mixing console and one FI-WP2V dual channel UHF wireless microphone enhance the performance and versatility of the sound system.</p>\n<p>It guarantees a clear, dynamic, adjustable and reliable sound which intensifies the travel into the luscious welcoming wilderness El Tiki embarks you upon.</p>\n<img alt=\"\" src=\"uploads/2018/02/El-Tiki-Tapas-Cocktail-Bar-Esotico.jpg\"/> <p><b>Interior concept: </b>MTM Design</p>\n<p><b>Sound Design: </b>Marc Vincent</p>\n<p><b>Installation and commissioning: </b>Icarus Group</p>','uploads/2020/10/El-Tiki-Tapas-Cocktail-Bar-Esotico-photo1.jpg',1,'2020-10-18 03:33:32',NULL,'2020-10-18 03:33:32','2025-04-09 12:05:02'),(7,'italo-gastro-lounge-in-shanghai','Italo, gastro lounge in Shanghai','Italo, gastro lounge in Shanghai Italo, the casual chic restaurant designed by MTM Design, is the latest groovy venue opened by Funka Group. Its classy Italian dishes are cooked with fresh premium products and a modern…','<p><strong>Italo, gastro lounge in Shanghai</strong></p>\n<p>Italo, the casual chic restaurant designed by MTM Design, is the latest groovy venue opened by Funka Group.</p>\n<p>Its classy Italian dishes are cooked with fresh premium products and a modern twist, by Roman chef Gonzo, and can be cozily relished in the spacious, refined dining-room.</p>\n<p>A nice selection of natural wines and a wide variety of craft cocktails come to pair the tasty meals and for pre- or post- dinner aperitifs.</p>\n<p>The sleek lounge bar provides the perfect setting to enjoy Italo’s creative drinks, mixed in cooperation with Campari Academy Milan.</p>\n<p>The ambience gets especially funky on weekends when the bar hosts live DJ sets.</p>\n<p>Eight discreet and elegant FS15-Arrays powered by 4 compact FS-Sub15 provide all the powerful sound necessary to please the DJ fans on weekend nights, while subtle when diffusing background music on dining hours. Two FI-SMS4B two-way speakers, one FI-Sub6P ultra-compact subwoofer and 2 FI-CS4W ceiling speakers are powered by two FI-Amp4D class D amplifiers to cover all other areas of the venue.</p>\n<p>One FI-P4X8+ digital speaker processor allows easy, intuitive configuration and control of the speakers.</p>\n<p>Two FI-Mix8 compact analog 8 In x 2 Out mixing consoles and 1 FI-WP2V dual channel UHF wireless microphone enhance the performance and versatility of the sound system, which delivers a powerful high quality sound throughout the whole venue.</p>\n<p>Frog-Is speakers diffuse a perfectly clear sound that can be both softly enfolding or powerful according to the various needs of the venue.</p>\n<img alt=\"\" src=\"uploads/2020/10/Italo-gastro-lounge-in-Shanghai-1.jpg\"/> <p><b>Interior concept: </b>MTM Design</p>\n<p><b>Sound Design: </b>Marc Vincent</p>\n<p><b>Installation and commissioning: </b>Shanghai Sound Wings</p>','uploads/2020/09/Italo-gastro-lounge-in-Shanghai-2.jpg',1,'2020-09-10 15:41:20',NULL,'2020-09-10 15:41:20','2025-04-09 12:05:43'),(8,'bibendum-adipiscing-phasellus-incididunt-2','Frog-is international training session: the Philippines','Frog-is international training session: the Philippines Frog-is is an innovative pro-audio company, truly international at heart with headquarters in Hong-Kong, factory in Ningbo and R&D in Florence. Taking the best of…','<p><strong>Frog-is international training session: the Philippines</strong></p>\n<p>Frog-is is an innovative pro-audio company, truly international at heart with headquarters in Hong-Kong, factory in Ningbo and R&amp;D in Florence.</p>\n<p>Taking the best of technology from Europe and Asia, Frog-is provides all the equipment needed to deliver a high quality sound at minimal price in all kinds of public meeting spaces: speakers, amplifiers, mixing consoles, microphones, wireless microphones, speaker processors and accessories.</p>\n<p>Frog-is is a one-stop shop for any demanding sound engineer, rental company owner, restaurant and bar operators having to work on restrictive budgets.</p>\n<p>For Frog-is, being modern, inventive and professional, goes together with being fun, bouncing, and full of humor!</p>\n<p>Chairman of Frog-is, Marc Vincent held a training session to present the brand and its products in the Philippines. 135 prospective clients were invited in an event room in Manilla to attend the session that took on festive tones as Marc Vincent had invited a singer and his musicians to let the guests listen to Frog-is new speakers.</p>\n<p>Frog-is distribution and after sales service are handled by Westco Electrical &amp; Equipment Corp. in</p>\n<p>the Philippines. “Frog-is offers an unprecedented quality / price ratio for professional audio prodcuts“ says director of Sales &amp; Marketing, Jek (Vincent) Penalosa. ‘‘The products are original, and allow us to offer our clients an excellent audio quality for the budgets available. We have already completed multiple installations where clients are totally satisfied’’.</p>\n<p>Most of the participants appreciated this initiative a lot. We are convinced that it is important to go and see the clients directly and create a joyful trust relationship with them.</p>\n<p>The clients must have the opportunity to test the products and to listen to them live (on stage) in order to get an idea of the high quality of the sound they offer.</p>\n<p>The guests listened to the compact self-powered full range speakers FP8, FP12 et FP15, and to the very manageable PA sound system FS15 which features 12 x 3,25’’ speakers and a 15’’ powerful subwoofer.</p>\n<p>During the two-day training, other products were also displayed: wireless microphones, mixing consoles…Frog-is can organize training sessions all around the world.</p>\n<img alt=\"\" src=\"uploads/2019/10/Philippines.jpg\"/> <img alt=\"\" src=\"uploads/2019/10/IMG_18601.png\"/>','uploads/2019/10/Philippines-2-scaled.jpg',1,'2020-02-18 15:54:01',NULL,'2020-02-18 15:54:01','2025-04-09 12:06:08'),(9,'bibendum-adipiscing-phasellus-incididunt','Frog-is is an innovative pro-audio company','Frog-is is an innovative pro-audio company Frog-is is an innovative pro-audio company, truly international at heart with headquarters in Hong-Kong, factory in Ningbo and R&D in Florence. Taking the best of technology…','<p><strong>Frog-is is an innovative pro-audio company</strong></p>\n<p>Frog-is is an innovative pro-audio company, truly international at heart with headquarters in Hong-Kong, factory in Ningbo and R&amp;D in Florence.</p>\n<p>Taking the best of technology from Europe and Asia, Frog-is provides all the equipment needed to deliver a high quality sound at minimal price in all kinds of public meeting spaces: speakers, amplifiers, mixing consoles, microphones, wireless microphones, speaker processors and accessories.</p>\n<p>Frog-is is a one-stop shop for any demanding sound engineer, rental company owner, restaurant and bar operators having to work on restrictive budgets.</p>\n<p>For Frog-is, being modern, inventive and professional, goes together with being fun, bouncing, and full of humor!</p>\n<img alt=\"\" src=\"uploads/2020/01/FROG-IS-HK.jpg\"/>','uploads/2018/02/Sans-titre-4-scaled.jpg',1,'2020-01-06 03:32:31',NULL,'2020-01-06 03:32:31','2025-04-09 12:06:45');
